import styled from '@emotion/styled';

interface StyledCustomAgGridTooltipProps {
  $darkMode?: boolean;
}

export const StyledCustomAgGridTooltip =
  styled.div<StyledCustomAgGridTooltipProps>(({ $darkMode }) => ({
    padding: '1rem',
    borderRadius: '16px',
    boxShadow: '0px 0px 8px 0px #00000029',
    position: 'relative',
    ...($darkMode === true && {
      background: '#141414',
      color: '#ffffff',
      padding: '0.5rem',
      borderRadius: '0.5rem',

      '&::before': {
        content: '""',
        position: 'absolute',
        top: '-8px',
        left: '50%',
        transform: 'translateX(-50%)',
        width: '0',
        height: '0',
        borderLeft: '8px solid transparent',
        borderRight: '8px solid transparent',
        borderBottom: '8px solid #141414',
      },
    }),
    ...($darkMode === false && {
      background: '#ffffff',
      color: '#141414',

      '&::before': {
        content: '""',
        position: 'absolute',
        top: '-8px',
        left: '50%',
        transform: 'translateX(-50%)',
        width: '0',
        height: '0',
        borderLeft: '8px solid transparent',
        borderRight: '8px solid transparent',
        borderBottom: '8px solid #ffffff',
      },
    }),
  }));
